 checks=[('Source-data preservation','ACCEPTABLE','Every original row/cell and all 198336 changes independently reconciled; hashes unchanged.'),('Cost Center coding accuracy','ACCEPTABLE WITH REVIEW','Native reference code values match; financial-domain/authority review remains for flagged populations.'),('Bank-name assignment validity','ACCEPTABLE WITH REVIEW','150648 same-row propagations, not Bank Master lookup; 245 account/fund naming cases require review; no Bank ID validated.'),('Organizational Unit mapping integrity','ACCEPTABLE WITH REVIEW','168915 formulas evaluate consistently with valid native code/name, but document lookup does not authorize line responsibility.'),('Person-reference consistency','ACCEPTABLE WITH REVIEW','37 same-ID variant groups, 35 alef/diacritic review and 2 invisible-format groups; 588 normalized-name multi-ID groups; no merges authorized.'),('Semantic matching reliability','ACCEPTABLE WITH REVIEW','Independent risk sample and full affected-population scans identify review risks; no source-master approval follows from unique budget joins.'),('Dimension-specific coverage','NOT YET ACCEPTABLE','Unknown applicability remains; bank identity/person authority/contract/project completeness unestablished.'),('Governance readiness','NOT YET ACCEPTABLE','No approved native-to-proposed CC crosswalk; historical relationships and candidate decisions not active ERP rules; privacy approval required.'),('Audit reproducibility','ACCEPTABLE','Standalone read-only scripts, row-level evidence, measured metrics and immutable hashes.')]
 lines=['# Independent Audit — Accounting Journal 1404 v1','','## Scope and overall acceptance','**ACCEPTABLE WITH REVIEW for restricted analytical/expert review; NOT YET ACCEPTABLE for authoritative ERP handoff.** No v1 file was overwritten and no v2 workbook was created.','All metrics below derive from independent paired workbook parsing, independent reference checks and dimensional audits—not copied execution figures.','',f'Source: `{SOURCE}`',f'Immutable output: `{V1 / "Accounting_Journal_1404_Desired_State_Enriched_v1.xlsx"}`','',f"Rows independently compared: **{m['measured']['rows']:,}**; unique region/document pairs: **{m['unique_region_document_pairs']:,}**; added cells: **{sum(m['added'].values()):,}**; all source-cell evidence checks: **{entry['counts']['entries']:,}**; preservation failures: **{len(m['preservation_failures'])}**; protected source/v1 hashes unchanged: **{entry['hashes_unchanged']}**.",'','## Cost Center population transitions','','| Initial cohort | Applied | Conflict | Proposed | Ambiguous | No evidence | Total |','|---|---:|---:|---:|---:|---:|---:|']
 for initial in ['INITIAL_UNIQUE','INITIAL_AMBIGUOUS','BUDGET_NOT_FOUND','UNUSABLE_BUDGET']:
  values={r['final']:r['rows'] for r in m['transitions'] if r['initial']==initial}
  numbers=[values.get(k,0) for k in ['APPLIED','CONFLICT','PROPOSED_MATCH','AMBIGUOUS','NO_EVIDENCE']]
  lines.append('| '+initial+' | '+' | '.join(f'{n:,}' for n in numbers+[sum(numbers)])+' |')
 lines+=['','All46015 expense rows have candidate reference rows, financial classifications and exclusion explanations in Cost_Center_Coverage_Reconciliation.csv. 23243 rows received native codes; 19886 came from initially unique and3357 from initially ambiguous associations. Existing names plus accounting constraints narrowed candidates; this is source-context lookup, not expert approval.','', '## Conflict taxonomy']
 for k,n in tax['conflict_taxonomy'].items():lines.append(f'- {k}: **{n:,}** rows.')
 lines+=['','The26494 revenue rows retain original expense-center names. Revenue_Field_Usage_Investigation.csv tests exact same-budget/native name correspondence and account-class consistency. No supplied field-use policy, dated assignment history or approval establishes legitimate historical revenue-center use. Therefore neither “legitimate” nor “erroneous original” is asserted as proven. The expense reference relationship cannot authorize expense allocation on revenue; preserve and escalate source-owner field semantics.','', '## Bank assignment evidence',json.dumps(m['bank_evidence'],ensure_ascii=False,indent=2),'Every assignment uses O<same source row> copied into AM. Source I611/native bank-account hierarchy plus P membership in bank reference C substantiates structured name propagation. It is not an authoritative Bank Master lookup and validates no AL ID. 211 rows lack bank-name tokens in account titles (often petty-cash account descriptions);34 rows name صندوق کارآفرینی امید rather than a bank. Full records retain accounting context and exact source cells.','', '## Independent match classification',json.dumps(m['independent_match_classes'],indent=2),'All original VALIDATED_COMPOSITE statuses remain untouched. Independent labels describe evidence:150648 SAME_ROW_STRUCTURED_FIELD_PROPAGATION;47688 CONTEXT_FILTERED_NATIVE_REFERENCE_LOOKUP. No approved Bank Master lookup exists. CC source-native code lookup is deterministic but account/domain compatibility and original name agreement are filters, not proof of a formally validated composite identifier or published ERP authorization.','', '## Organizational formulas',json.dumps(org['counts'],ensure_ascii=False,indent=2),'All168915 existing AD VLOOKUP formulas were independently evaluated, cache matched, native code/name valid. No blank/error/mismatch or multi-unit filter key was found.384752 rows have no formula/code. Formula existence and computational validity remain separately measured from approved line responsibility.','', '## Person exceptions','All141738 native pairs preserved.37 same-ID variant groups affect865 rows:35 alef/madda/diacritic similarity groups affect791;2 invisible-format groups affect74. No dated evidence proves name changes.588 normalized-name multi-ID groups affect54152 rows; similar names are not grounds to merge IDs. Person_Master_Exceptions.csv gives rows/variants; proposed_person_corrections.csv is analytical display normalization only, never an authoritative identity correction.','', '## Eligibility and coverage',json.dumps(elig,ensure_ascii=False,indent=2),'Eligibility is positive observed source/reference evidence, not a global mandatory-field rule. Explicit NOT_APPLICABLE population is0: absence is never used to establish nonapplicability. Cost Center rates show physical code recovery and no-detected-contradiction separately; neither is committee-authorized coverage. Bank name coverage and Bank ID coverage differ; Person ID/name presence does not prove authoritative identity/role consistency. Contract/project eligible denominator is unestablished, so rates are not reported as0% or100%.','', '## Risk-based semantic audit',json.dumps(sem,ensure_ascii=False,indent=2),'Semantic_Cost_Center_Audit.csv contains at least300 distinct newly assigned CC rows. full_population_findings.csv covers systemic rules beyond the sample, including original unchanged CC context. Keyword/domain tensions are REVIEW triggers, not arbitrary authoritative corrections. Any proposed candidates retain explicit approval requirements.','', '## Every original REVIEW','See QA_REVIEW_Explanations.md: QA_Controls8 (contract/project evidence), QA_Controls15 (privacy/distribution), Independent_QA15 (same missing contract/project coverage). All remain REVIEW; zero unsafe fills is not complete coverage, local execution is not ACL/security approval.','', '## Required governance evidence','Signed/versioned native F/H→enterprise CC crosswalk with effective dates, approving authority, domain constraints and split/merge lineage; approved ERP master; authoritative event relationships/applicability/cardinalities; transaction-line contract/project/person-role links; Bank Master IDs/accounts and ownership; source field-use policy; privacy/release authorization. Historical event relations remain OBSERVED — NOT AUTHORIZED.','', '## Explicit acceptance assessments','','| Area | Assessment | Evidence and limitation |','|---|---|---|']
 for area,status,evidence in checks:lines.append(f'| {area} | **{status}** | {evidence} |')
 lines+=['','## Correction boundary','No enriched v2 is justified by this audit. Proposed person display normalization and CC contextual alternatives require approval before mutation. No safe authoritative identity/domain replacement has been established merely from these analytical findings.','', '## Reproduction','Run scripts/audit_journal_1404_independent.py once into a new empty audit directory; scripts/audit_journal_1404_org_person.py and reviews script read workbooks directly; semantic script reads completed local journal_records.sqlite; entries/conflicts/eligibility/report scripts consume independently produced evidence. The protected-file hash manifest and entry verification preserve original/v1 immutability. Do not rerun into an existing SQLite index without selecting a fresh directory.','', 'Detailed row-level files contain financial/person information. Restrict access; do not circulate full CSVs as unrestricted management exports.']
 (ROOT/'Independent_Audit_Report_EN.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 fa=['# خلاصه مدیریتی ممیزی مستقل دفتر ۱۴۰۴','نسخه v1 و فایل اصلی بدون تغییر باقی ماندند؛ نسخه v2 تولید نشد.','حفظ داده‌های مالی و همه۱۹۸٬۳۳۶ تکمیل با کنترل مستقل و شواهد ردیفی بررسی شد. انتساب بومی مرکز هزینه در۲۳٬۲۴۳ ردیف از۴۶٬۰۱۵ ردیف هزینه وجود دارد؛ یکتایی اتصال بودجه به معنای تصویب مالی نیست.','۲۶٬۴۹۴ ردیف درآمدی از قبل عنوان مرکز هزینه داشته‌اند؛ بدون سیاست کاربری فیلد و سابقه تأیید، قانونی یا اشتباه بودن تاریخی قطعی نیست. مقادیر حفظ و برای تصمیم مالک داده ارجاع شد.','۱۵۰٬۶۴۸ نام بانک از سرفصل همان ردیف منتقل شده‌اند، نه مرجع شناسه بانک؛۲۴۵ مورد نیازمند بازبینی هستند. هیچ شناسه بانک تأیید نشده است.','۱۶۸٬۹۱۵ فرمول واحد سازمانی مستقل محاسبه شد؛ نتیجه با حافظه فایل و کد/نام بومی منطبق است؛ این انطباق مجوز مسئولیت در سطح خط حسابداری نیست.','۳۷ گروه اختلاف نام برای شناسه شخص حفظ شد؛۳۵ گروه نیازمند بررسی املایی و۲ گروه اختلاف نویسه نامرئی است. شباهت نام مجوز ادغام شناسه نیست.','موارد بازبینی معنایی و کل جامعه متاثر در گزارش مستقل ثبت شده؛ تکمیل ظاهری از صحت معنایی و حاکمیت تفکیک شده است.','نتیجه: برای بازبینی کارشناسی محدود «قابل قبول با بررسی»؛ برای تحویل حاکمیتی ERP هنوز «قابل قبول نیست». کراس‌واک مصوب، قواعد کاربرد ابعاد، مراجع شناسه و مجوز محرمانگی لازم است.']
 (ROOT/'Management_Summary_FA.md').write_text('\n\n'.join(fa)+'\n',encoding='utf-8')
 print('Independent report and Persian management summary created.')
